from dataclasses import dataclass
from datetime import datetime
# 橙色便利贴「订单已创建」→ 领域事件类
@dataclass(frozen=True)
class OrderCreated:
    order_id: str
    customer_id: str
    occurred_at: datetime
# 橙色便利贴「支付已完成」→ 领域事件类
@dataclass(frozen=True)
class PaymentCompleted:
    payment_id: str
    order_id: str
    amount_in_cents: int
    occurred_at: datetime
# 紫色便利贴「当支付完成时 → 通知仓库发货」→ 策略类
class WhenPaymentCompletedThenNotifyWarehouse:
    def __init__(self, warehouse_service):
        self._warehouse = warehouse_service
    def handle(self, event: PaymentCompleted):
        self._warehouse.prepare_shipment(
            order_id=event.order_id
        )
